(()=>{document.querySelectorAll('[data-consult-topic]').forEach(button=>button.addEventListener('click',()=>{const select=document.getElementById('q-topic');select.value=button.dataset.consultTopic;select.dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('lich-tu-van').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});select.focus({preventScroll:true});}));})();
